class _LightingSettingsState extends State<LightingSettings> { LightingControlMode mode = LightingControlMode.manualVerification; double simulatedLux = 20; final service = LightWakeService(); @override Widget build(BuildContext context) { final setup = LightingSetup(mode: mode, smartLightName: mode == LightingControlMode.smartLight ? 'Bedroom lights' : null); final decision = service.evaluate(setup: setup, reading: LightSensorReading(lux: simulatedLux, capturedAt: DateTime.now())); return Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Wake lighting', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 8), RadioListTile<LightingControlMode>(title: const Text('Control smart lights automatically'), subtitle: const Text('RISE turns lights on when the alarm fires.'), value: LightingControlMode.smartLight, groupValue: mode, onChanged: (value) => setState(() => mode = value ?? mode)), RadioListTile<LightingControlMode>(title: const Text('Require lights on manually'), subtitle: const Text('If smart control is unavailable, RISE requires you to turn lights on and verifies brightness with the phone light sensor.'), value: LightingControlMode.manualVerification, groupValue: mode, onChanged: (value) => setState(() => mode = value ?? mode)), ListTile(title: Text('Detected light: ${simulatedLux.round()} lux'), subtitle: Slider(value: simulatedLux, min: 0, max: 500, divisions: 10, label: '${simulatedLux.round()} lux', onChanged: (value) => setState(() => simulatedLux = value))), Text(decision.message), const SizedBox(height: 8), FilledButton(onPressed: decision.isRoomBrightEnough ? null : () => setState(() => simulatedLux = 180), child: const Text('Simulate lights turned on'))]))); } }
